using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_5481a9ee5408430eb2848c9ad7f780af.Client.Auth;

namespace sv_5481a9ee5408430eb2848c9ad7f780af.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user
/// and persists the auth state to PersistentComponentState for WebAssembly handoff.
/// </summary>
public sealed class FakeAuthenticationStateProvider : AuthenticationStateProvider, IHostedService, IDisposable
{
    private readonly PersistentComponentState _state;
    private PersistingComponentStateSubscription _subscription;

    private static readonly AuthenticationState _authState = CreateAuthState();

    public FakeAuthenticationStateProvider(PersistentComponentState state)
    {
        _state = state;
        _subscription = state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    private static AuthenticationState CreateAuthState()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "FakeAuth");
        return new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authState);

    private Task OnPersistingAsync()
    {
        var principal = _authState.User;
        var email = principal.FindFirst(ClaimTypes.Email)?.Value;
        var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

        _state.PersistAsJson(nameof(UserInfo), new UserInfo
        {
            Email = email!,
            Roles = roles,
        });

        return Task.CompletedTask;
    }

    public Task StartAsync(CancellationToken cancellationToken) => Task.CompletedTask;
    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

